1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const FIRST_INSURANCE_RATE = 0.1;
49	
50	const withFirstInsuranceSurcharge = (policyBase: number): number =>
51	  policyBase + policyBase * FIRST_INSURANCE_RATE;
52	
53	const COMPONENT_BLOCK_SIZE = 3;
54	const COMPONENT_BLOCK_PREMIUM = 60;
55	
56	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
57	
58	const policyBasePremium = (items: Item[]): number => {
59	  if (
60	    items.length === COMPONENT_BLOCK_SIZE &&
61	    items.every((item) => item.type === "rune")
62	  ) {
63	    return COMPONENT_BLOCK_PREMIUM;
64	  }
65	  return items.reduce((sum, item) => sum + basePremiumOf(item), 0);
66	};
67	
68	const quotePremium = (items: Item[]): number =>
69	  withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE;
70	
71	const runStep = (step: Step): StepResult => {
72	  if (step.op === "quote") return { premium: quotePremium(step.items) };
73	  throw new Error(`unsupported step: ${step.op}`);
74	};
75	
76	export const runScenario = (scenario: Scenario): ScenarioResult => ({
77	  results: scenario.steps.map(runStep),
78	});
